    // segacrpt: table bits -> D3 D5 D7, inverted together when the source D7 was set
    wire [7:0] t1   = {q[2], 1'b0, q[1], 1'b0, q[0], 3'b000} ^ (s[7] ? 8'hA8 : 8'h00);
