        case (q[8:4])
            5'd0: begin sw[6] = s[6]; sw[4] = s[4]; sw[2] = s[2]; sw[0] = s[0]; end
            5'd1: begin sw[6] = s[4]; sw[4] = s[6]; sw[2] = s[2]; sw[0] = s[0]; end
            5'd2: begin sw[6] = s[2]; sw[4] = s[4]; sw[2] = s[6]; sw[0] = s[0]; end
            5'd3: begin sw[6] = s[0]; sw[4] = s[4]; sw[2] = s[2]; sw[0] = s[6]; end
            5'd4: begin sw[6] = s[6]; sw[4] = s[2]; sw[2] = s[4]; sw[0] = s[0]; end
            5'd5: begin sw[6] = s[6]; sw[4] = s[0]; sw[2] = s[2]; sw[0] = s[4]; end
            5'd6: begin sw[6] = s[6]; sw[4] = s[4]; sw[2] = s[0]; sw[0] = s[2]; end
            5'd7: begin sw[6] = s[2]; sw[4] = s[6]; sw[2] = s[4]; sw[0] = s[0]; end
            5'd8: begin sw[6] = s[4]; sw[4] = s[2]; sw[2] = s[6]; sw[0] = s[0]; end
            5'd9: begin sw[6] = s[4]; sw[4] = s[6]; sw[2] = s[0]; sw[0] = s[2]; end
            5'd10: begin sw[6] = s[6]; sw[4] = s[0]; sw[2] = s[4]; sw[0] = s[2]; end
            5'd11: begin sw[6] = s[0]; sw[4] = s[6]; sw[2] = s[4]; sw[0] = s[2]; end
            5'd12: begin sw[6] = s[4]; sw[4] = s[0]; sw[2] = s[6]; sw[0] = s[2]; end
            5'd13: begin sw[6] = s[0]; sw[4] = s[4]; sw[2] = s[6]; sw[0] = s[2]; end
            5'd14: begin sw[6] = s[6]; sw[4] = s[2]; sw[2] = s[0]; sw[0] = s[4]; end
            5'd15: begin sw[6] = s[2]; sw[4] = s[6]; sw[2] = s[0]; sw[0] = s[4]; end
            5'd16: begin sw[6] = s[0]; sw[4] = s[6]; sw[2] = s[2]; sw[0] = s[4]; end
            5'd17: begin sw[6] = s[2]; sw[4] = s[0]; sw[2] = s[6]; sw[0] = s[4]; end
            5'd18: begin sw[6] = s[0]; sw[4] = s[2]; sw[2] = s[6]; sw[0] = s[4]; end
            5'd19: begin sw[6] = s[4]; sw[4] = s[2]; sw[2] = s[0]; sw[0] = s[6]; end
            5'd20: begin sw[6] = s[2]; sw[4] = s[4]; sw[2] = s[0]; sw[0] = s[6]; end
            5'd21: begin sw[6] = s[4]; sw[4] = s[0]; sw[2] = s[2]; sw[0] = s[6]; end
            5'd22: begin sw[6] = s[2]; sw[4] = s[0]; sw[2] = s[4]; sw[0] = s[6]; end
            5'd23: begin sw[6] = s[0]; sw[4] = s[2]; sw[2] = s[4]; sw[0] = s[6]; end
            default: ;
        endcase
    end
    wire [7:0] out2 = sw ^ {1'b0, q[3], 1'b0, q[2], 1'b0, q[1], 1'b0, q[0]};

    always_comb begin
        if (!enc)           dout = s;
        else if (k == 2'd1) dout = out1;
        else                dout = out2;
    end

